-- No provider calls: transaction-scoped synthetic reservation/authorization checks.
RESET ROLE;
INSERT INTO auth.users(id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) VALUES('f1d00000-0000-4000-8000-000000000001','authenticated','authenticated','workshop-presenter@firstten-demo.invalid','','{}','{}',now(),now()) ON CONFLICT(id) DO NOTHING;
INSERT INTO public.projects(id,user_id,name,checklist) VALUES('f1d00000-0000-4000-8000-000000000010','f1d00000-0000-4000-8000-000000000001','Fictional budget policy fixture','{}') ON CONFLICT(id) DO NOTHING;
UPDATE auth.users SET raw_app_meta_data=coalesce(raw_app_meta_data,'{}')||'{"firstten_demo_admin":true,"synthetic":true,"firstten_demo_fixture":"first-ten-babson-2026-10-18-v1"}'::jsonb WHERE id='f1d00000-0000-4000-8000-000000000001';
UPDATE public.projects SET checklist=jsonb_set(checklist,'{demo}','{"fictional":true,"fixtureVersion":"first-ten-babson-2026-10-18-v1"}') WHERE id='f1d00000-0000-4000-8000-000000000010' AND user_id='f1d00000-0000-4000-8000-000000000001';
INSERT INTO firstten_policy_test.ids(label,id) VALUES('demo_ai_actor','f1d00000-0000-4000-8000-000000000001');
SELECT ok(NOT has_table_privilege('authenticated','firstten_private.demo_ai_budget','SELECT,INSERT,UPDATE,DELETE'),'browser cannot inspect or reset private global budget');
SELECT ok(NOT has_table_privilege('service_role','firstten_private.demo_ai_reservations','SELECT,INSERT,UPDATE,DELETE'),'service role receives no direct ledger grant');
SELECT ok(NOT has_function_privilege('anon','public.reserve_demo_ai(uuid,uuid)','EXECUTE'),'anonymous cannot reserve budget');
SELECT ok(NOT has_function_privilege('service_role','public.reserve_demo_ai(uuid,uuid)','EXECUTE'),'service role cannot bypass reservation identity checks');
SELECT ok((SELECT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] FROM pg_proc WHERE oid='public.reserve_demo_ai(uuid,uuid)'::regprocedure),'reservation function has fixed privileged scope');
SELECT is((SELECT reserved_cents::int FROM firstten_private.demo_ai_budget),0,'isolated fixture starts with no reserved AI spend');
SELECT firstten_policy_test.set_actor('owner_a');
SET LOCAL ROLE authenticated;
SELECT is(public.reserve_demo_ai('f1d00000-0000-4000-8000-000000000010',gen_random_uuid())->>'code','FORBIDDEN','ordinary owner cannot reserve synthetic budget');
SELECT is(firstten_policy_test.attempt($case$SELECT * FROM firstten_private.demo_ai_budget$case$),'error:42501','browser cannot query internal budget table');
RESET ROLE;
SELECT firstten_policy_test.set_actor('demo_ai_actor');
SET LOCAL ROLE authenticated;
SELECT is(public.reserve_demo_ai(firstten_policy_test.id('project_b'),gen_random_uuid())->>'code','FORBIDDEN','synthetic admin cannot reserve for a different project');
SELECT is(public.reserve_demo_ai('f1d00000-0000-4000-8000-000000000010',NULL)->>'code','FORBIDDEN','reservation requires explicit request UUID');
SELECT is(public.reserve_demo_ai('f1d00000-0000-4000-8000-000000000010','f7000000-0000-4000-8000-000000000001'),'{"ok":true,"reservedCents":2,"remainingCents":98}'::jsonb,'fresh trusted synthetic presenter reserves two cents');
SELECT is(public.reserve_demo_ai('f1d00000-0000-4000-8000-000000000010','f7000000-0000-4000-8000-000000000001')->>'code','ALREADY_RESERVED','same request cannot authorize a second provider call');
RESET ROLE;
SELECT is((SELECT reserved_cents::int FROM firstten_private.demo_ai_budget),2,'retry does not reserve twice');
UPDATE auth.users SET raw_app_meta_data=raw_app_meta_data||'{"firstten_demo_admin":false}'::jsonb WHERE id='f1d00000-0000-4000-8000-000000000001';
-- Keep a stale JWT claiming the grant; live auth row revocation is authoritative.
SELECT set_config('request.jwt.claims','{"sub":"f1d00000-0000-4000-8000-000000000001","role":"authenticated","app_metadata":{"firstten_demo_admin":true,"synthetic":true}}',true);
SET LOCAL ROLE authenticated;
SELECT is(public.reserve_demo_ai('f1d00000-0000-4000-8000-000000000010',gen_random_uuid())->>'code','FORBIDDEN','revocation defeats stale trusted-looking JWT claims');
RESET ROLE;
UPDATE auth.users SET raw_app_meta_data=raw_app_meta_data||'{"firstten_demo_admin":true,"synthetic":false}'::jsonb WHERE id='f1d00000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT is(public.reserve_demo_ai('f1d00000-0000-4000-8000-000000000010',gen_random_uuid())->>'code','FORBIDDEN','admin flag alone does not authorize real-user contexts');
RESET ROLE;
UPDATE auth.users SET raw_app_meta_data=raw_app_meta_data||'{"synthetic":true,"firstten_demo_fixture":"wrong-version"}'::jsonb WHERE id='f1d00000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT is(public.reserve_demo_ai('f1d00000-0000-4000-8000-000000000010',gen_random_uuid())->>'code','FORBIDDEN','wrong trusted fixture version denied');
RESET ROLE;
UPDATE auth.users SET raw_app_meta_data=raw_app_meta_data||'{"firstten_demo_fixture":"first-ten-babson-2026-10-18-v1"}'::jsonb WHERE id='f1d00000-0000-4000-8000-000000000001';
UPDATE public.projects SET checklist=jsonb_set(checklist,'{demo,fictional}','false') WHERE id='f1d00000-0000-4000-8000-000000000010';
SET LOCAL ROLE authenticated;
SELECT is(public.reserve_demo_ai('f1d00000-0000-4000-8000-000000000010',gen_random_uuid())->>'code','FORBIDDEN','missing fictional project marker fails closed');
RESET ROLE;
SELECT is((SELECT reserved_cents::int FROM firstten_private.demo_ai_budget),2,'denied requests do not consume or change budget');
UPDATE public.projects SET checklist=jsonb_set(checklist,'{demo,fictional}','true') WHERE id='f1d00000-0000-4000-8000-000000000010';
SET LOCAL ROLE authenticated;
DO $$ DECLARE response jsonb; BEGIN FOR i IN 2..50 LOOP response:=public.reserve_demo_ai('f1d00000-0000-4000-8000-000000000010',('f7000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid); IF response->>'ok'<>'true' THEN RAISE EXCEPTION 'Synthetic reservation fixture failed'; END IF; END LOOP; END $$;
SELECT is(public.reserve_demo_ai('f1d00000-0000-4000-8000-000000000010',gen_random_uuid()),'{"ok":false,"code":"BUDGET_EXHAUSTED","remainingCents":0}'::jsonb,'global one-dollar cap rejects request fifty-one');
SELECT is(public.reserve_demo_ai('f1d00000-0000-4000-8000-000000000010','f7000000-0000-4000-8000-000000000001')->>'code','ALREADY_RESERVED','retry remains denied after budget is full');
RESET ROLE;
SELECT is((SELECT reserved_cents::int FROM firstten_private.demo_ai_budget),100,'global reserved budget never exceeds one dollar');
SELECT is((SELECT count(*) FROM firstten_private.demo_ai_reservations),50::bigint,'only fifty synthetic request reservations exist');
SELECT is((SELECT sum(reserved_cents)::int FROM firstten_private.demo_ai_reservations),100,'global counter equals bounded reservation ledger');
SELECT ok(NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='firstten_private' AND table_name='demo_ai_reservations' AND column_name IN ('prompt','output','notes','email','provider_response')),'ledger stores no prompt, output or participant content');
